package edu.bis701.exp02;
public class MatrixMultiplication {static void print(int[][]m){for(int[]r:m){for(int x:r)System.out.printf("%d\t",x);System.out.println();}}public static void main(String[]args){int[][]a={{1,2},{3,4}},b={{5,6},{7,8}};if(a[0].length!=b.length)throw new IllegalArgumentException("Incompatible dimensions");int[][]c=new int[a.length][b[0].length];System.out.println("Matrix A:");print(a);System.out.println("Matrix B:");print(b);for(int i=0;i<a.length;i++)for(int j=0;j<b[0].length;j++)for(int k=0;k<b.length;k++)c[i][j]+=a[i][k]*b[k][j];System.out.println("Product Matrix:");print(c);}}
